function createBaseServerMessage(): ServerMessage {
  return {
    error: undefined,
    chatReceived: undefined,
    gameState: undefined,
    wonGame: undefined,
    action: undefined,
    actionHistory: undefined,
  };
}

export const ServerMessage: MessageFns<ServerMessage> = {
  encode(message: ServerMessage, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.error !== undefined) {
      Error.encode(message.error, writer.uint32(10).fork()).join();
    }
    if (message.chatReceived !== undefined) {
      ChatReceived.encode(message.chatReceived, writer.uint32(18).fork()).join();
    }
    if (message.gameState !== undefined) {
      GameState.encode(message.gameState, writer.uint32(26).fork()).join();
    }
    if (message.wonGame !== undefined) {
      WonGame.encode(message.wonGame, writer.uint32(34).fork()).join();
    }
    if (message.action !== undefined) {
      Action.encode(message.action, writer.uint32(42).fork()).join();
    }
    if (message.actionHistory !== undefined) {
      ActionHistory.encode(message.actionHistory, writer.uint32(50).fork()).join();
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): ServerMessage {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseServerMessage();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 10) {
            break;
          }

          message.error = Error.decode(reader, reader.uint32());
          continue;
        }
        case 2: {
          if (tag !== 18) {
            break;
          }

          message.chatReceived = ChatReceived.decode(reader, reader.uint32());
          continue;
        }
        case 3: {
          if (tag !== 26) {
            break;
          }

          message.gameState = GameState.decode(reader, reader.uint32());
          continue;
        }
        case 4: {
          if (tag !== 34) {
            break;
          }

          message.wonGame = WonGame.decode(reader, reader.uint32());
          continue;
        }
        case 5: {
          if (tag !== 42) {
            break;
          }

          message.action = Action.decode(reader, reader.uint32());
          continue;
        }
        case 6: {
          if (tag !== 50) {
            break;
          }

          message.actionHistory = ActionHistory.decode(reader, reader.uint32());
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): ServerMessage {
    return {
      error: isSet(object.error) ? Error.fromJSON(object.error) : undefined,
      chatReceived: isSet(object.chatReceived)
        ? ChatReceived.fromJSON(object.chatReceived)
        : isSet(object.chat_received)
        ? ChatReceived.fromJSON(object.chat_received)
        : undefined,
      gameState: isSet(object.gameState)
        ? GameState.fromJSON(object.gameState)
        : isSet(object.game_state)
        ? GameState.fromJSON(object.game_state)
        : undefined,
      wonGame: isSet(object.wonGame)
        ? WonGame.fromJSON(object.wonGame)
        : isSet(object.won_game)
        ? WonGame.fromJSON(object.won_game)
        : undefined,
      action: isSet(object.action) ? Action.fromJSON(object.action) : undefined,
      actionHistory: isSet(object.actionHistory)
        ? ActionHistory.fromJSON(object.actionHistory)
        : isSet(object.action_history)
        ? ActionHistory.fromJSON(object.action_history)
        : undefined,
    };
  },

  toJSON(message: ServerMessage): unknown {
    const obj: any = {};
    if (message.error !== undefined) {
      obj.error = Error.toJSON(message.error);
    }
    if (message.chatReceived !== undefined) {
      obj.chatReceived = ChatReceived.toJSON(message.chatReceived);
    }
    if (message.gameState !== undefined) {
      obj.gameState = GameState.toJSON(message.gameState);
    }
    if (message.wonGame !== undefined) {
      obj.wonGame = WonGame.toJSON(message.wonGame);
    }
    if (message.action !== undefined) {
      obj.action = Action.toJSON(message.action);
    }
    if (message.actionHistory !== undefined) {
      obj.actionHistory = ActionHistory.toJSON(message.actionHistory);
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<ServerMessage>, I>>(base?: I): ServerMessage {
    return ServerMessage.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<ServerMessage>, I>>(object: I): ServerMessage {
    const message = createBaseServerMessage();
    message.error = (object.error !== undefined && object.error !== null) ? Error.fromPartial(object.error) : undefined;
    message.chatReceived = (object.chatReceived !== undefined && object.chatReceived !== null)
      ? ChatReceived.fromPartial(object.chatReceived)
      : undefined;
    message.gameState = (object.gameState !== undefined && object.gameState !== null)
      ? GameState.fromPartial(object.gameState)
      : undefined;
    message.wonGame = (object.wonGame !== undefined && object.wonGame !== null)
      ? WonGame.fromPartial(object.wonGame)
      : undefined;
    message.action = (object.action !== undefined && object.action !== null)
      ? Action.fromPartial(object.action)
      : undefined;
    message.actionHistory = (object.actionHistory !== undefined && object.actionHistory !== null)
      ? ActionHistory.fromPartial(object.actionHistory)
      : undefined;
    return message;
  },
};

type Builtin = Date | Function | Uint8Array | string | number | boolean | undefined;

export type DeepPartial<T> = T extends Builtin ? T
  : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

type KeysOfUnion<T> = T extends T ? keyof T : never;
export type Exact<P, I extends P> = P extends Builtin ? P
  : P & { [K in keyof P]: Exact<P[K], I[K]> } & { [K in Exclude<keyof I, KeysOfUnion<P>>]: never };

function longToNumber(int64: { toString(): string }): number {
  const num = globalThis.Number(int64.toString());
  if (num > globalThis.Number.MAX_SAFE_INTEGER) {
    throw new globalThis.Error("Value is larger than Number.MAX_SAFE_INTEGER");
  }
  if (num < globalThis.Number.MIN_SAFE_INTEGER) {
    throw new globalThis.Error("Value is smaller than Number.MIN_SAFE_INTEGER");
  }
  return num;
}

function isSet(value: any): boolean {
  return value !== null && value !== undefined;
}

export interface MessageFns<T> {
  encode(message: T, writer?: BinaryWriter): BinaryWriter;
  decode(input: BinaryReader | Uint8Array, length?: number): T;
  fromJSON(object: any): T;
  toJSON(message: T): unknown;
  create<I extends Exact<DeepPartial<T>, I>>(base?: I): T;
  fromPartial<I extends Exact<DeepPartial<T>, I>>(object: I): T;
}
